module ietf-network {
  namespace "urn:ietf:params:xml:ns:yang:ietf-network";
  prefix nw;

  organization
    "IETF I2RS (Interface to the Routing System) Working Group";
  contact
    "WG Web:    <https://datatracker.ietf.org/wg/i2rs/>
     WG List:   <mailto:i2rs@ietf.org>

     Editor:    Alexander Clemm
                <mailto:ludwig@clemm.org>

     Editor:    Jan Medved
                <mailto:jmedved@cisco.com>

     Editor:    Robert Varga
                <mailto:robert.varga@pantheon.tech>

     Editor:    Nitin Bahadur
                <mailto:nitin_bahadur@yahoo.com>

     Editor:    Hariharan Ananthakrishnan
                <mailto:hari@packetdesign.com>

     Editor:    Xufeng Liu
                <mailto:xufeng.liu.ietf@gmail.com>";
  description
    "This module defines a common base data model for a collection
     of nodes in a network.  Node definitions are further used
     in network topologies and inventories.

     Copyright (c) 2018 IETF Trust and the persons identified as
     authors of the code.  All rights reserved.

     Redistribution and use in source and binary forms, with or
     without modification, is permitted pursuant to, and subject
     to the license terms contained in, the Simplified BSD License
     set forth in Section 4.c of the IETF Trust's Legal Provisions
     Relating to IETF Documents
     (https://trustee.ietf.org/license-info).

     This version of this YANG module is part of RFC 8345;
     see the RFC itself for full legal notices.";

  revision 2018-02-26;

  container networks {
    config true;
    status current;
    description
      "Serves as a top-level container for a list of networks.";
    list network {
      key "network-id";
      config true;
      min-elements 0;
      max-elements 4294967295;
      ordered-by system;
      status current;
      description
        "Describes a network.
         A network typically contains an inventory of nodes,
         topological information (augmented through the
         network-topology data model), and layering information.";
      leaf network-id {
        type string {
          pattern "[a-z][a-z0-9+.-]*:.*";
        }
        config true;
        status current;
        description
          "Identifies a network.";
      }
      container network-types {
        config true;
        status current;
        description
          "Serves as an augmentation target.
           The network type is indicated through corresponding
           presence containers augmented into this container.";
      }
      list supporting-network {
        key "network-ref";
        config true;
        min-elements 0;
        max-elements 4294967295;
        ordered-by system;
        status current;
        description
          "An underlay network, used to represent layered network
           topologies.";
        leaf network-ref {
          type leafref {
            path "/nw:networks/nw:network/nw:network-id";
            require-instance false;
            type string {
              pattern "[a-z][a-z0-9+.-]*:.*";
            }
          }
          config true;
          status current;
          description
            "References the underlay network.";
        }
      }
      list node {
        key "node-id";
        config true;
        min-elements 0;
        max-elements 4294967295;
        ordered-by system;
        status current;
        description
          "The inventory of nodes of this network.";
        leaf node-id {
          type string {
            pattern "[a-z][a-z0-9+.-]*:.*";
          }
          config true;
          status current;
          description
            "Uniquely identifies a node within the containing
             network.";
        }
        list supporting-node {
          key "network-refnode-ref";
          config true;
          min-elements 0;
          max-elements 4294967295;
          ordered-by system;
          status current;
          description
            "Represents another node that is in an underlay network
             and that supports this node.  Used to represent layering
             structure.";
          leaf network-ref {
            type leafref {
              path "../../../nw:supporting-network/nw:network-ref";
              require-instance false;
              type string {
                pattern "[a-z][a-z0-9+.-]*:.*";
              }
            }
            config true;
            status current;
            description
              "References the underlay network of which the
               underlay node is a part.";
          }
          leaf node-ref {
            type leafref {
              path "/nw:networks/nw:network/nw:node/nw:node-id";
              require-instance false;
              type string {
                pattern "[a-z][a-z0-9+.-]*:.*";
              }
            }
            config true;
            status current;
            description
              "References the underlay node itself.";
          }
        }
        list termination-point {
          key "tp-id";
          config true;
          min-elements 0;
          max-elements 4294967295;
          ordered-by system;
          status current;
          description
            "A termination point can terminate a link.
             Depending on the type of topology, a termination point
             could, for example, refer to a port or an interface.";
          leaf tp-id {
            type string {
              pattern "[a-z][a-z0-9+.-]*:.*";
            }
            config true;
            status current;
            description
              "Termination point identifier.";
          }
          list supporting-termination-point {
            key "network-refnode-reftp-ref";
            config true;
            min-elements 0;
            max-elements 4294967295;
            ordered-by system;
            status current;
            description
              "This list identifies any termination points on which a
               given termination point depends or onto which it maps.
               Those termination points will themselves be contained
               in a supporting node.  This dependency information can be
               inferred from the dependencies between links.  Therefore,
               this item is not separately configurable.  Hence, no
               corresponding constraint needs to be articulated.
               The corresponding information is simply provided by the
               implementing system.";
            leaf network-ref {
              type leafref {
                path "../../../nw:supporting-node/nw:network-ref";
                require-instance false;
                type string {
                  pattern "[a-z][a-z0-9+.-]*:.*";
                }
              }
              config true;
              status current;
              description
                "This leaf identifies in which topology the
                 supporting termination point is present.";
            }
            leaf node-ref {
              type leafref {
                path "../../../nw:supporting-node/nw:node-ref";
                require-instance false;
                type string {
                  pattern "[a-z][a-z0-9+.-]*:.*";
                }
              }
              config true;
              status current;
              description
                "This leaf identifies in which node the supporting
                 termination point is present.";
            }
            leaf tp-ref {
              type leafref {
                path "/nw:networks/nw:network[nw:network-id=current()/../network-ref]/nw:node[nw:node-id=current()/../node-ref]/termination-point/tp-id";
                require-instance false;
                type string {
                  pattern "[a-z][a-z0-9+.-]*:.*";
                }
              }
              config true;
              status current;
              description
                "Reference to the underlay node (the underlay node must
                 be in a different topology).";
            }
          }
        }
      }
      list link {
        key "link-id";
        config true;
        min-elements 0;
        max-elements 4294967295;
        ordered-by system;
        status current;
        description
          "A network link connects a local (source) node and
           a remote (destination) node via a set of the respective
           node's termination points.  It is possible to have several
           links between the same source and destination nodes.
           Likewise, a link could potentially be re-homed between
           termination points.  Therefore, in order to ensure that we
           would always know to distinguish between links, every link
           is identified by a dedicated link identifier.  Note that a
           link models a point-to-point link, not a multipoint link.";
        leaf link-id {
          type string {
            pattern "[a-z][a-z0-9+.-]*:.*";
          }
          config true;
          status current;
          description
            "The identifier of a link in the topology.
             A link is specific to a topology to which it belongs.";
        }
        container source {
          config true;
          status current;
          description
            "This container holds the logical source of a particular
             link.";
          leaf source-node {
            type leafref {
              path "../../../nw:node/nw:node-id";
              require-instance false;
              type string {
                pattern "[a-z][a-z0-9+.-]*:.*";
              }
            }
            config true;
            status current;
            description
              "Source node identifier.  Must be in the same topology.";
          }
          leaf source-tp {
            type leafref {
              path "../../../nw:node[nw:node-id=current()/../source-node]/termination-point/tp-id";
              require-instance false;
              type string {
                pattern "[a-z][a-z0-9+.-]*:.*";
              }
            }
            config true;
            status current;
            description
              "This termination point is located within the source node
               and terminates the link.";
          }
        }
        container destination {
          config true;
          status current;
          description
            "This container holds the logical destination of a
             particular link.";
          leaf dest-node {
            type leafref {
              path "../../../nw:node/nw:node-id";
              require-instance false;
              type string {
                pattern "[a-z][a-z0-9+.-]*:.*";
              }
            }
            config true;
            status current;
            description
              "Destination node identifier.  Must be in the same
               network.";
          }
          leaf dest-tp {
            type leafref {
              path "../../../nw:node[nw:node-id=current()/../dest-node]/termination-point/tp-id";
              require-instance false;
              type string {
                pattern "[a-z][a-z0-9+.-]*:.*";
              }
            }
            config true;
            status current;
            description
              "This termination point is located within the
               destination node and terminates the link.";
          }
        }
        list supporting-link {
          key "network-reflink-ref";
          config true;
          min-elements 0;
          max-elements 4294967295;
          ordered-by system;
          status current;
          description
            "Identifies the link or links on which this link depends.";
          leaf network-ref {
            type leafref {
              path "../../../nw:supporting-network/nw:network-ref";
              require-instance false;
              type string {
                pattern "[a-z][a-z0-9+.-]*:.*";
              }
            }
            config true;
            status current;
            description
              "This leaf identifies in which underlay topology
               the supporting link is present.";
          }
          leaf link-ref {
            type leafref {
              path "/nw:networks/nw:network[nw:network-id=current()/../network-ref]/link/link-id";
              require-instance false;
              type string {
                pattern "[a-z][a-z0-9+.-]*:.*";
              }
            }
            config true;
            status current;
            description
              "This leaf identifies a link that is a part
               of this link's underlay.  Reference loops in which
               a link identifies itself as its underlay, either
               directly or transitively, are not allowed.";
          }
        }
      }
    }
  }
}
